    // ------------------------------------------------------------------
    // Block 0 is primarily used for the interrupt vectors code, stack,
    // heap and DM data.
    // If the entire block3 is cache (128KB size) it also includes priority
    // code section.

			

			
				#define IV_CODE seg_rth
			
			
				#define IV_CODE dxe_iv_code
			



				
